"""Independent reference implementation of PROTOCOL.md (slow but literal)."""
import json
from collections import deque


def bfs(adj, src):
    dist = [-1] * len(adj)
    dist[src] = 0
    q = deque([src])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] < 0:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist


class Topology:
    def __init__(self, spec):
        self.spec = spec
        mode = spec[0]
        self.adj = []
        self.cache_nodes = set()
        self.endpoints = []
        self.domain = None
        self.pairs = []          # ordered (src,dst) template list
        if mode == 'clos':
            k, scope, intra = spec[1], spec[2], spec[3]
            r = k // 2
            tors = k * r
            self.n = 2 * tors
            core = 2 * tors
            adj = [[] for _ in range(self.n + 1)]
            for tor in range(tors):
                pod = tor // r
                for a in range(r):
                    agg = tors + pod * r + a
                    adj[tor].append(agg); adj[agg].append(tor)
            for agg in range(tors, 2 * tors):
                adj[agg].append(core); adj[core].append(agg)
            self.adj = adj
            self.cache_nodes = set(range(2 * tors))
            self.endpoints = list(range(tors))
            if scope == 'tor':
                self.domain = lambda s, d: s
            else:
                self.domain = lambda s, d: s // r
            for s in range(tors):
                for d in range(tors):
                    if s == d: continue
                    if not intra and s // r == d // r: continue
                    self.pairs.append((s, d))
        elif mode == 'leaf-spine':
            leaves, spines = spec[1], spec[2]
            self.n = leaves + spines
            adj = [[] for _ in range(self.n)]
            for leaf in range(leaves):
                for sp in range(leaves, self.n):
                    adj[leaf].append(sp); adj[sp].append(leaf)
            self.adj = adj
            self.cache_nodes = set(range(leaves))
            self.endpoints = list(range(leaves))
            self.domain = lambda s, d: s
            for s in range(leaves):
                for d in range(leaves):
                    if s != d: self.pairs.append((s, d))
        elif mode in ('torus2d', 'torus3d'):
            n = spec[1]; scope = spec[2]
            dim = 2 if mode == 'torus2d' else 3
            self.n = n ** dim
            adj = [[] for _ in range(self.n)]
            def nid(*coords):
                idx = 0
                for c in coords: idx = idx * n + c
                return idx
            axes = [1, 0, 0], [0, 1, 0], [0, 0, 1]
            for idx in range(self.n):
                coords = []
                rest = idx
                for _ in range(dim):
                    coords.append(rest % n); rest //= n
                coords = coords[::-1]
                for a in range(dim):
                    for sign in (1, -1):
                        nxt = list(coords)
                        nxt[a] = (coords[a] + sign) % n
                        v = nid(*nxt)
                        if v not in adj[idx]:
                            adj[idx].append(v)
            self.adj = adj
            self.cache_nodes = set(range(self.n))
            self.endpoints = list(range(self.n))
            if scope == 'host':
                self.domain = lambda s, d: s
            elif mode == 'torus2d':
                self.domain = lambda s, d: s // n
            else:
                self.domain = lambda s, d: s // n
            for s in range(self.n):
                for d in range(self.n):
                    if s != d: self.pairs.append((s, d))
        elif mode == 'dragonfly':
            g, a, h, scope = spec[1], spec[2], spec[3], spec[4]
            self.n = g * a
            adj = [[] for _ in range(self.n)]
            def rid(group, idx): return group * a + idx
            for group in range(g):
                for i in range(a):
                    for j in range(i + 1, a):
                        u = rid(group, i); v = rid(group, j)
                        adj[u].append(v); adj[v].append(u)
            for g1 in range(g):
                for g2 in range(g1 + 1, g):
                    delta = g2 - g1
                    i1 = (delta - 1) // h
                    i2 = (g - delta - 1) // h
                    u = rid(g1, i1); v = rid(g2, i2)
                    adj[u].append(v); adj[v].append(u)
            self.adj = adj
            self.cache_nodes = set(range(self.n))
            self.endpoints = list(range(self.n))
            if scope == 'router':
                self.domain = lambda s, d: s
            elif scope == 'group':
                self.domain = lambda s, d: s // a
            else:
                self.domain = lambda s, d: s * g + d // a
            for s in range(self.n):
                for d in range(self.n):
                    if s != d: self.pairs.append((s, d))
        elif mode == 'dragonfly-plus':
            g, l, s, h, dense, scope = spec[1], spec[2], spec[3], spec[4], spec[5], spec[6]
            sw = l + s
            self.n = g * sw
            adj = [[] for _ in range(self.n)]
            def leaf(group, idx): return group * sw + idx
            def spine(group, idx): return group * sw + l + idx
            for group in range(g):
                for i in range(l):
                    for j in range(s):
                        u = leaf(group, i); v = spine(group, j)
                        adj[u].append(v); adj[v].append(u)
            if dense:
                for g1 in range(g):
                    for g2 in range(g1 + 1, g):
                        for j in range(s):
                            u = spine(g1, j); v = spine(g2, j)
                            adj[u].append(v); adj[v].append(u)
            else:
                for g1 in range(g):
                    for g2 in range(g1 + 1, g):
                        delta = g2 - g1
                        s1 = (delta - 1) // h
                        s2 = (g - delta - 1) // h
                        u = spine(g1, s1); v = spine(g2, s2)
                        adj[u].append(v); adj[v].append(u)
            self.adj = adj
            self.cache_nodes = set(range(self.n))
            self.endpoints = []
            for group in range(g):
                for i in range(l):
                    self.endpoints.append(leaf(group, i))
            if scope == 'group':
                self.domain = lambda s, d: s // sw
            else:
                self.domain = lambda s, d: (s // sw) * l + (s % sw)
            for s in self.endpoints:
                for d in self.endpoints:
                    if s != d: self.pairs.append((s, d))
        else:
            raise ValueError('topology')
        # distances and footprints
        dists = [bfs(self.adj, s) for s in range(len(self.adj))]
        self.fp = []
        for (s, d) in self.pairs:
            best = dists[s][d]
            fp = set()
            for v in self.cache_nodes:
                if dists[s][v] >= 0 and dists[d][v] >= 0 and dists[s][v] + dists[d][v] == best:
                    fp.add(v)
            self.fp.append(frozenset(fp))
        self.domains = [self.domain(s, d) for (s, d) in self.pairs]


class State:
    def __init__(self, topo, caps, groups, tasks):
        self.topo = topo
        self.caps = list(caps)
        self.quota = [g[0] for g in groups]
        self.budget = [g[1] for g in groups]
        self.template = [t[0] for t in tasks]
        self.group = [t[1] for t in tasks]
        self.weight = [t[2] for t in tasks]
        self.class_ = [t[3] for t in tasks]
        self.pinned = [t[4] for t in tasks]

    def copy(self):
        s = State.__new__(State)
        s.topo = self.topo
        s.caps = list(self.caps)
        s.quota = list(self.quota); s.budget = list(self.budget)
        s.template = list(self.template); s.group = list(self.group)
        s.weight = list(self.weight); s.class_ = list(self.class_)
        s.pinned = list(self.pinned)
        return s

    def group_members(self):
        out = [[] for _ in self.quota]
        for t, g in enumerate(self.group):
            out[g].append(t)
        return out

    def group_fp(self):
        members = self.group_members()
        fps = []
        for g, ts in enumerate(members):
            fp = set()
            for t in ts:
                fp |= self.topo.fp[self.template[t]]
            fps.append(fp)
        return fps

    def usage(self):
        fps = self.group_fp()
        use = [0] * self.topo.n
        for g, fp in enumerate(fps):
            if not fp: continue
            for node in fp:
                use[node] += self.quota[g]
        return use

    def loads(self):
        load = [0] * len(self.quota)
        for t in range(len(self.group)):
            load[self.group[t]] += self.weight[t]
        return load

    def keys(self):
        members = self.group_members()
        out = []
        for ts in members:
            out.append(set((self.topo.domains[self.template[t]], self.class_[t]) for t in ts))
        return out

    def violations(self):
        topo = self.topo
        use = self.usage()
        cap = sum(1 for n in range(topo.n) if use[n] > self.caps[n])
        keys = self.keys()
        mixed = sum(1 for k in keys if len(k) > 1)
        load = self.loads()
        work = 0
        for g in range(len(self.quota)):
            if len(keys[g]) == 0: continue
            if self.quota[g] == 0 or load[g] > self.quota[g] * self.budget[g]:
                work += 1
        return [cap, mixed, work, 0]

    def certificate(self, query):
        topo = self.topo
        members = self.group_members()
        fps = self.group_fp()
        load = self.loads()
        use = self.usage()
        keys = self.keys()
        active = sum(1 for g in range(len(self.quota)) if members[g])
        slots = sum(use)
        weight = sum(self.weight)
        pins = sum(1 for p in self.pinned if p)
        grows = []
        for g in query['groups']:
            if members[g]:
                k = sorted(keys[g])[0]
                d, c = k
            else:
                d, c = -1, -1
            grows.append([g, len(members[g]), load[g], self.quota[g], self.budget[g], len(fps[g]), d, c])
        nrows = [[n, use[n], self.caps[n]] for n in query['nodes']]
        trows = [[t, self.group[t], self.template[t], self.weight[t], self.class_[t], self.pinned[t]]
                 for t in query['tasks']]
        return {'totals': [active, slots, weight, pins], 'groups': grows, 'nodes': nrows, 'tasks': trows}


def pin_violations(old, new):
    """Count protected tasks violated by a proposal."""
    count = 0
    for t in range(len(old.pinned)):
        if not old.pinned[t]: continue
        if (new.template[t] != old.template[t] or new.group[t] != old.group[t]
                or new.weight[t] != old.weight[t] or new.class_[t] != old.class_[t]):
            count += 1
            continue
        if new.quota[old.group[t]] != old.quota[old.group[t]]:
            count += 1
    return count


def apply_edits(state, edits):
    for edit in edits:
        op = edit[0]
        if op == 'move':
            state.group[edit[1]] = edit[2]
        elif op == 'weight':
            state.weight[edit[1]] = edit[2]
        elif op == 'class':
            state.class_[edit[1]] = edit[2]
        elif op == 'bind':
            state.template[edit[1]] = edit[2]
        elif op == 'pin':
            state.pinned[edit[1]] = edit[2]
        elif op == 'quota':
            state.quota[edit[1]] = edit[2]
        elif op == 'budget':
            state.budget[edit[1]] = edit[2]
        elif op == 'cap':
            state.caps[edit[1]] = edit[2]
        else:
            raise ValueError('edit')


def legal(state):
    v = state.violations()
    return v[0] == 0 and v[1] == 0 and v[2] == 0


def run_session(session):
    topo = Topology(session['topology'])
    state = State(topo, session['caps'], session['groups'], session['tasks'])
    if not legal(state):
        raise ValueError('illegal initial configuration')
    out = {'nodes': topo.n, 'templates': len(topo.pairs),
           'initial': state.certificate(session['query']), 'transactions': []}
    revision = 0
    for tx in session['transactions']:
        if tx['revision'] != revision:
            out['transactions'].append({'accepted': False, 'revision': revision, 'violations': None,
                                        'certificate': state.certificate(tx['query'])})
            continue
        proposal = state.copy()
        apply_edits(proposal, tx['edits'])
        v = proposal.violations()
        v[3] = pin_violations(state, proposal)
        accepted = all(x == 0 for x in v)
        if accepted:
            state = proposal
            revision += 1
        out['transactions'].append({'accepted': accepted, 'revision': revision, 'violations': v,
                                    'certificate': state.certificate(tx['query'])})
    return out


def run(request):
    results = []
    for session in request['sessions']:
        results.append(run_session(session))
    return {'sessions': results}
